sys_script.script:
(function executeRule(current, previous) {

    var offerings = current.getValue('offerings') || '';

    // Normalize line endings and remove unnecessary spaces
    offerings = offerings
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .trim();

    var errors = [];

    // Split into individual lines
    var lines = offerings.split('\n');

    // Helper function to get the value after a label
    function getValueAfterLabel(label) {

        for (var i = 0; i < lines.length; i++) {

            var line = lines[i].trim();

            if (line.indexOf(label) === 0) {
                return line.substring(label.length).trim();
            }
        }

        return '';
    }

    // Get values
    var salary = getValueAfterLabel('Salary Offered:');
    var bonus = getValueAfterLabel('Bonus Offered:');
    var workMode = getValueAfterLabel('Work Mode Offered(On-site / Hybrid / Remote):');
    var workingHours = getValueAfterLabel('Working Hours Offered:');
    var others = getValueAfterLabel('Others:');

    // Salary validation
    if (!salary || salary.indexOf('___') !== -1) {
        errors.push('Salary Offered');
    }

    // Bonus validation
    if (!bonus) {
        errors.push('Bonus Offered');
    }

    // Work mode validation
    if (!workMode) {
        errors.push('Work Mode Offered');
    }

    // Working hours validation
    if (!workingHours) {
        errors.push('Working Hours Offered');
    }

    // Others validation
    if (!others) {
        errors.push('Others');
    }

    // Stop record creation
    if (errors.length > 0) {

        gs.addErrorMessage(
            'Please fill in the following Offerings fields before creating the Job Requisition: ' +
            errors.join(', ')
        );

        current.setAbortAction(true);
    }

})(current, previous);
